  ($str$variable$str$, 'USA', $str$2026-Additive$str$, $str$slsBaseLayersHeight$str$, $str$15$str$, $str$Length$str$, $str$The default height of the powder between the build platform and the first part to be built.$str$, $jsonb${"Variable Name":"slsBaseLayersHeight","String Value":15,"Unit Type Name":"Length","Notes":"The default height of the powder between the build platform and the first part to be built.","Group":"Inherited"}$jsonb$::jsonb),
