  ($str$variable$str$, 'USA', $str$2026-Additive$str$, $str$slsFitBuildPlateTime$str$, $str$1200$str$, $str$Time$str$, $str$The typical time it takes to fit and level the build plate in the machine bed.$str$, $jsonb${"Variable Name":"slsFitBuildPlateTime","String Value":1200,"Unit Type Name":"Time","Notes":"The typical time it takes to fit and level the build plate in the machine bed.","Group":"Inherited"}$jsonb$::jsonb),
