  ($str$variable$str$, 'USA', $str$2026-Additive$str$, $str$slsPowderFeedRiseFactor$str$, $str$2.25$str$, NULL, $str$A factor applied to the layer thickness. Ensures the powder feed platform rises enough so there is enough powder to cover the build platform.$str$, $jsonb${"Variable Name":"slsPowderFeedRiseFactor","String Value":2.25,"Unit Type Name":null,"Notes":"A factor applied to the layer thickness. Ensures the powder feed platform rises enough so there is enough powder to cover the build platform.","Group":"Inherited"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Additive$str$, $str$slsPrepBuildChamber$str$, $str$1200$str$, $str$Time$str$, $str$The typical time it takes to prepare the build chamber for printing parts including cleaning laser lens and lens cover.$str$, $jsonb${"Variable Name":"slsPrepBuildChamber","String Value":1200,"Unit Type Name":"Time","Notes":"The typical time it takes to prepare the build chamber for printing parts including cleaning laser lens and lens cover.","Group":"Inherited"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Additive$str$, $str$usePreferredMachines$str$, $str$true$str$, NULL, $str$If true the model will first try to select a preferred machine. If false, the system chooses either the default machine or from the entire non-preferred set of machines.$str$, $jsonb${"Variable Name":"usePreferredMachines","String Value":true,"Unit Type Name":null,"Notes":"If true the model will first try to select a preferred machine. If false, the system chooses either the default machine or from the entire non-preferred set of machines.","Group":"Inherited"}$jsonb$::jsonb),
