INSERT INTO machining_reference_data (category, source_region, source_version, key, value, unit_type, notes, raw) VALUES
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$EBWDepthFactor$str$, $str$0.25$str$, NULL, $str$Factor used to calculate welding speed from weld penetration and machine power$str$, $jsonb${"Variable Name":"EBWDepthFactor","String Value":0.25,"Unit Type Name":null,"Notes":"Factor used to calculate welding speed from weld penetration and machine power"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$EBWMaximumWeldDepth$str$, $str$100$str$, $str$Length$str$, $str$Maximum weld depth feasible for Electron Beam Welding$str$, $jsonb${"Variable Name":"EBWMaximumWeldDepth","String Value":100,"Unit Type Name":"Length","Notes":"Maximum weld depth feasible for Electron Beam Welding"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$EBWMinPartSpacing$str$, $str$50$str$, $str$Length$str$, $str$Minimum part spacing when multiple parts are loaded in the chamber$str$, $jsonb${"Variable Name":"EBWMinPartSpacing","String Value":50,"Unit Type Name":"Length","Notes":"Minimum part spacing when multiple parts are loaded in the chamber"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$EBWPowerFactor$str$, $str$5$str$, NULL, $str$Factor used to calculate welding speed from weld penetration and machine power$str$, $jsonb${"Variable Name":"EBWPowerFactor","String Value":5,"Unit Type Name":null,"Notes":"Factor used to calculate welding speed from weld penetration and machine power"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$EBWSpeedFactor$str$, $str$1.5$str$, NULL, $str$Factor used to calculate welding speed from weld penetration and machine power$str$, $jsonb${"Variable Name":"EBWSpeedFactor","String Value":1.5,"Unit Type Name":null,"Notes":"Factor used to calculate welding speed from weld penetration and machine power"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$LWEfficiencyFactor$str$, $str$20$str$, NULL, $str$Efficiency Factor used to calculate the welding speed from the power of the laser and depth of the weld$str$, $jsonb${"Variable Name":"LWEfficiencyFactor","String Value":20,"Unit Type Name":null,"Notes":"Efficiency Factor used to calculate the welding speed from the power of the laser and depth of the weld"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$LWMaximumWeldDepth$str$, $str$20$str$, $str$Length$str$, $str$Maximum weld depth achievable with Laser Welding$str$, $jsonb${"Variable Name":"LWMaximumWeldDepth","String Value":20,"Unit Type Name":"Length","Notes":"Maximum weld depth achievable with Laser Welding"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$LWMinPartSpacing$str$, $str$50$str$, $str$Length$str$, $str$Minimum part spacing when multiple parts are loaded on a pallet$str$, $jsonb${"Variable Name":"LWMinPartSpacing","String Value":50,"Unit Type Name":"Length","Notes":"Minimum part spacing when multiple parts are loaded on a pallet"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$additionalClampAreaFraction$str$, $str$0.1$str$, NULL, $str$If the area of a Contact Region gcd in relation to the possible area (length x width) is less than this value additional clamps are used.$str$, $jsonb${"Variable Name":"additionalClampAreaFraction","String Value":0.1,"Unit Type Name":null,"Notes":"If the area of a Contact Region gcd in relation to the possible area (length x width) is less than this value additional clamps are used."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$arcEfficiency$str$, $str$0.86$str$, NULL, $str$Estimate of the percentage of welding wire that actually ends up in the weld. Adjusts weld deposition rate to account for loss due to spatter and evaporation. Used to calculate arcing time and tack time.$str$, $jsonb${"Variable Name":"arcEfficiency","String Value":0.86,"Unit Type Name":null,"Notes":"Estimate of the percentage of welding wire that actually ends up in the weld. Adjusts weld deposition rate to account for loss due to spatter and evaporation. Used to calculate arcing time and tack time."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$clampForTackAndWeld$str$, $str$false$str$, NULL, $str$If true, there will be two clamping operations assigned to contact groups with an associated weld. One for tacking and one for welding.$str$, $jsonb${"Variable Name":"clampForTackAndWeld","String Value":false,"Unit Type Name":null,"Notes":"If true, there will be two clamping operations assigned to contact groups with an associated weld. One for tacking and one for welding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$cycleTimeAdjustmentFactor$str$, $str$1$str$, NULL, $str$Factor used to globally increase or decrease cycle time evaluations per process.$str$, $jsonb${"Variable Name":"cycleTimeAdjustmentFactor","String Value":1,"Unit Type Name":null,"Notes":"Factor used to globally increase or decrease cycle time evaluations per process."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultFixturePartNumberClampOperations$str$, $str$0$str$, NULL, $str$Number of clamp operations applied to fixture part. Used to determine default behavior of fixturePartNumberClampOperations PSO.$str$, $jsonb${"Variable Name":"defaultFixturePartNumberClampOperations","String Value":0,"Unit Type Name":null,"Notes":"Number of clamp operations applied to fixture part. Used to determine default behavior of fixturePartNumberClampOperations PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultFixtureVolumeFactor$str$, $str$1.1$str$, NULL, $str$Factor applied to component geometry to derive fixture volume. Used to determine default value of fixtureVolume PSO.$str$, $jsonb${"Variable Name":"defaultFixtureVolumeFactor","String Value":1.1,"Unit Type Name":null,"Notes":"Factor applied to component geometry to derive fixture volume. Used to determine default value of fixtureVolume PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultHornMaterial$str$, $str$Aluminum 7075$str$, NULL, $str$Material of ultrasonic horn. Used to determine default value of hornMaterial PSO.$str$, $jsonb${"Variable Name":"defaultHornMaterial","String Value":"Aluminum 7075","Unit Type Name":null,"Notes":"Material of ultrasonic horn. Used to determine default value of hornMaterial PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultHornTravelTime$str$, $str$3$str$, $str$Time$str$, $str$The total displacement time of the horn to initiate contact of the subcomponent and retract to starting position. Used to determine default value of hornTravelTime PSO.$str$, $jsonb${"Variable Name":"defaultHornTravelTime","String Value":3,"Unit Type Name":"Time","Notes":"The total displacement time of the horn to initiate contact of the subcomponent and retract to starting position. Used to determine default value of hornTravelTime PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultMIGWeldingMaterialType$str$, $str$Steel$str$, NULL, $str$Default material type of the assembly for MIG Welding. Material type must be defined as one of the material types from the list of materials specified in tblWeldTravelSpeed.$str$, $jsonb${"Variable Name":"defaultMIGWeldingMaterialType","String Value":"Steel","Unit Type Name":null,"Notes":"Default material type of the assembly for MIG Welding. Material type must be defined as one of the material types from the list of materials specified in tblWeldTravelSpeed."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultMachineTableConfiguration$str$, $str$Rotary$str$, NULL, $str$Default ultrasonic machine table configuration, Rotary or Bench. Used to populate default value of machineTableConfiguration PSO.$str$, $jsonb${"Variable Name":"defaultMachineTableConfiguration","String Value":"Rotary","Unit Type Name":null,"Notes":"Default ultrasonic machine table configuration, Rotary or Bench. Used to populate default value of machineTableConfiguration PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultMigWeldingGasType$str$, $str$Argon$str$, NULL, $str$Default type of shielding gas used for the MIG Welding processes. Gas type must be defined as one of the gases from the list of gas types specified in tblWeldTravelSpeed.$str$, $jsonb${"Variable Name":"defaultMigWeldingGasType","String Value":"Argon","Unit Type Name":null,"Notes":"Default type of shielding gas used for the MIG Welding processes. Gas type must be defined as one of the gases from the list of gas types specified in tblWeldTravelSpeed."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultNumberWeldingReorientations$str$, $str$0$str$, NULL, $str$Number of default reorientations required for Welding processes.$str$, $jsonb${"Variable Name":"defaultNumberWeldingReorientations","String Value":0,"Unit Type Name":null,"Notes":"Number of default reorientations required for Welding processes."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultPercentBonded$str$, $str$100$str$, NULL, $str$Default percent of a Contact Region surface area to be bonded.$str$, $jsonb${"Variable Name":"defaultPercentBonded","String Value":100,"Unit Type Name":null,"Notes":"Default percent of a Contact Region surface area to be bonded."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultResinThickness$str$, $str$0.002$str$, $str$m$str$, $str$Default thickness of resin on the bonded parts$str$, $jsonb${"Variable Name":"defaultResinThickness","String Value":0.002,"Unit Type Name":"m","Notes":"Default thickness of resin on the bonded parts"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultStakeCrossSectionArea$str$, $str$100$str$, $str$Area$str$, $str$Standard cross sectional area of predeformed ultrasonic stake. Used to determine default value of stakeCrossSectionArea PSO.$str$, $jsonb${"Variable Name":"defaultStakeCrossSectionArea","String Value":100,"Unit Type Name":"Area","Notes":"Standard cross sectional area of predeformed ultrasonic stake. Used to determine default value of stakeCrossSectionArea PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultTIGWeldingMaterialType$str$, $str$Steel$str$, NULL, $str$Default material type of the assembly for TIG Welding. Material type must be defined as one of the material types from the list of materials specified in tblTigWelding.$str$, $jsonb${"Variable Name":"defaultTIGWeldingMaterialType","String Value":"Steel","Unit Type Name":null,"Notes":"Default material type of the assembly for TIG Welding. Material type must be defined as one of the material types from the list of materials specified in tblTigWelding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultTigWeldingGasType$str$, $str$Argon$str$, NULL, $str$Default type of shielding gas used for the TIG Welding processes. Gas type must be defined as one of the gases from the list of gas types specified in tblTigWelding.$str$, $jsonb${"Variable Name":"defaultTigWeldingGasType","String Value":"Argon","Unit Type Name":null,"Notes":"Default type of shielding gas used for the TIG Welding processes. Gas type must be defined as one of the gases from the list of gas types specified in tblTigWelding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultUltrasonicInsertionTime$str$, $str$1.5$str$, $str$Time$str$, $str$Time taken to create an ultrasonic insertion. Used to determine default value of hornUltrasonicTime PSO.$str$, $jsonb${"Variable Name":"defaultUltrasonicInsertionTime","String Value":1.5,"Unit Type Name":"Time","Notes":"Time taken to create an ultrasonic insertion. Used to determine default value of hornUltrasonicTime PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultUltrasonicStakeTime$str$, $str$2$str$, $str$Time$str$, $str$Time taken to create an ultrasonic stake joint. Used to determine default value of hornUltrasonicTime PSO.$str$, $jsonb${"Variable Name":"defaultUltrasonicStakeTime","String Value":2,"Unit Type Name":"Time","Notes":"Time taken to create an ultrasonic stake joint. Used to determine default value of hornUltrasonicTime PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultUltrasonicWeldTime$str$, $str$2$str$, $str$Time$str$, $str$Time taken to create standard ultrasonic weld joint. Used to determine default value of hornUltrasonicTime PSO.$str$, $jsonb${"Variable Name":"defaultUltrasonicWeldTime","String Value":2,"Unit Type Name":"Time","Notes":"Time taken to create standard ultrasonic weld joint. Used to determine default value of hornUltrasonicTime PSO."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$defaultWeldingAssemblyPosition$str$, $str$Flat$str$, NULL, $str$Default position the assembly is placed before Welding. Position must be defined as one of the positions from the list of position types specified in tblTigWelding.$str$, $jsonb${"Variable Name":"defaultWeldingAssemblyPosition","String Value":"Flat","Unit Type Name":null,"Notes":"Default position the assembly is placed before Welding. Position must be defined as one of the positions from the list of position types specified in tblTigWelding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$degreaseApplicationRate$str$, $str$0.03$str$, $str$m^2/ min$str$, $str$Rate at which degrease solution is applied to the applicable area$str$, $jsonb${"Variable Name":"degreaseApplicationRate","String Value":0.03,"Unit Type Name":"m^2/ min","Notes":"Rate at which degrease solution is applied to the applicable area"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$disableInvestmentAmortization$str$, $str$false$str$, NULL, $str$User override to disable amortization of all fixed costs to the individual part or assembly. By default, fixed costs are calculated per part for tooling, fixtures, and programming.$str$, $jsonb${"Variable Name":"disableInvestmentAmortization","String Value":false,"Unit Type Name":null,"Notes":"User override to disable amortization of all fixed costs to the individual part or assembly. By default, fixed costs are calculated per part for tooling, fixtures, and programming."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$displaySumNumOperators$str$, $str$false$str$, NULL, $str$When true, the Number of Operators display field on the Assembly Details tab will display a summation of the number of operators for all Pick and Place operations. When false, the maximum number of operators will be displayed. This has no effect on the cost.$str$, $jsonb${"Variable Name":"displaySumNumOperators","String Value":false,"Unit Type Name":null,"Notes":"When true, the Number of Operators display field on the Assembly Details tab will display a summation of the number of operators for all Pick and Place operations. When false, the maximum number of operators will be displayed. This has no effect on the cost."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$enableTackingWithRoboticWelding$str$, $str$true$str$, NULL, $str$Enable a tacking operation for Robotic Welding. True by default, so MIG and TIG Robotic Welding will apply a tacking operation prior to Welding.$str$, $jsonb${"Variable Name":"enableTackingWithRoboticWelding","String Value":true,"Unit Type Name":null,"Notes":"Enable a tacking operation for Robotic Welding. True by default, so MIG and TIG Robotic Welding will apply a tacking operation prior to Welding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$failWeldsWithZeroCrossSectionArea$str$, $str$true$str$, NULL, $str$User override to control the consideration of zero GCD values for welding. False by default, zero GCD values are ignored and welding successfully but with some costs neglected. If set to true, it checks to see if the cross section area is less than are equal to zero and fails to cost welding.$str$, $jsonb${"Variable Name":"failWeldsWithZeroCrossSectionArea","String Value":true,"Unit Type Name":null,"Notes":"User override to control the consideration of zero GCD values for welding. False by default, zero GCD values are ignored and welding successfully but with some costs neglected. If set to true, it checks to see if the cross section area is less than are equal to zero and fails to cost welding."}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-Assembly$str$, $str$gearQualityDefaultAgmaNewStd$str$, $str$A8$str$, NULL, $str$A2, A3, A4, ... A11, A12$str$, $jsonb${"Variable Name":"gearQualityDefaultAgmaNewStd","String Value":"A8","Unit Type Name":null,"Notes":"A2, A3, A4, ... A11, A12"}$jsonb$::jsonb),
